 "content": "def transform(grid):
    """Fill the framed region and draw clipped square rings around its 3 marker."""
    out = [row[:] for row in grid]
    frame_rows = [r for r, row in enumerate(grid) if 3 in row]
    frame_cols = [c for row in grid for c, value in enumerate(row) if value == 3]
    top, bottom = min(frame_rows), max(frame_rows)
    left, right = min(frame_cols), max(frame_cols)
    r0, r1, c0, c1 = top + 1, bottom - 1, left + 1, right - 1
    marks = [(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
             if grid[r][c] == 3]
    if len(marks) != 1:
        return out
    mr, mc = marks[0]
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            out[r][c] = 4
    out[mr][mc] = 3
    max_radius = max(mr-r0, r1-mr, mc-c0, c1-mc)
    for radius in range(2, max_radius + 1, 2):
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if max(abs(r-mr), abs(c-mc)) == radius:
                    out[r][c] = 2
    return out
